class Gen<T> {}
class Gen2<T> : System.Attribute {}
class Gen3<T> : System.Attribute { Gen3(T parameter) { } }

[Gen]
[Gen2]
[Gen2()]
[Gen2<U>]
[Gen2<System.Collections.Generic.List<U>>]
[Gen3(1)]
public class Test<U>
{
	public static int Main()
	{
		return 1;
	}
}

